#![allow(
    clippy::expect_used,
    clippy::indexing_slicing,
    clippy::panic,
    clippy::too_many_lines,
    missing_docs,
    reason = "bounded ITF integration assertions; divergences must fail loudly"
)]
//! DRT adapter: Quint's ITF states are the oracle, not a Rust copy of the model.
//! Run with `NORN_QUINT_TRACE_DIR` pointing at traces generated by pinned Quint.
use std::collections::{BTreeMap, BTreeSet};
use std::path::{Path, PathBuf};

use norn_cell::engine::{NativeEngine, SqlEngine};
use norn_cell::{
    CellError, CellStore, CommitBatch, CommitOutcome, CommitPoint, Consumption, EffectRow,
    FactWriteRow, GuardedError, Model, OutboxCommand, StoreOptions, StoreReader,
};
use norn_ir::quantity_ledger::QuantityRequest;
use norn_ir::{ObjectTypeName, RuntimeValue};
use norn_kernel::decision_commit::TypeCatalog;
use norn_kernel::{
    CellCommit, CommitError, Consumed, FactKey, FactMutation, FactVersion, FactWrite, LinkKey,
};
use norn_kernel::{CommitModel, CommitView, check_commit};
use serde_json::{Value, json};

fn model() -> Model {
    let object = serde_json::from_value(json!({"name":"proof.Marker",
        "properties":[{"id":"v","type":{"kind":"integer"}}]}))
    .expect("definition");
    Model::from_definitions(&[object], &[]).expect("model")
}
fn runtime(v: Value) -> RuntimeValue {
    RuntimeValue::from_json(v).expect("exact small fixture")
}
fn number(v: &Value) -> i64 {
    v.as_i64().expect("bounded model integer")
}
fn text(v: &Value) -> &str {
    v.as_str().expect("model string")
}
fn normalize(v: Value) -> Value {
    match v {
        Value::Object(mut map) => {
            if let Some(n) = map.remove("#bigint") {
                return json!(text(&n).parse::<i64>().expect("bounded ITF integer"));
            }
            if let Some(list) = map.remove("#list") {
                return normalize(list);
            }
            Value::Object(map.into_iter().map(|(k, v)| (k, normalize(v))).collect())
        }
        Value::Array(xs) => Value::Array(xs.into_iter().map(normalize).collect()),
        other @ (Value::Null | Value::Bool(_) | Value::Number(_) | Value::String(_)) => other,
    }
}
fn traces(name: &str) -> Vec<(PathBuf, Vec<Value>)> {
    let root = std::env::var_os("NORN_QUINT_TRACE_DIR").map_or_else(
        || PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../verification/kernel-v2/traces"),
        PathBuf::from,
    );
    let mut paths = std::fs::read_dir(&root)
        .expect("generate Quint ITF traces first")
        .map(|entry| entry.expect("trace entry").path())
        .filter(|path| {
            path.file_name()
                .expect("name")
                .to_string_lossy()
                .starts_with(name)
                && path.extension().is_some_and(|ext| ext == "json")
        })
        .collect::<Vec<_>>();
    paths.sort();
    assert!(
        !paths.is_empty(),
        "no {name} ITF traces in {}",
        root.display()
    );
    paths
        .into_iter()
        .map(|path| {
            let raw: Value = serde_json::from_slice(&std::fs::read(&path).expect("trace bytes"))
                .expect("ITF JSON");
            let states = normalize(raw)["states"]
                .as_array()
                .expect("ITF states")
                .clone();
            assert!(states.len() > 1, "empty trace: {}", path.display());
            (path, states)
        })
        .collect()
}

struct View<'a, 'b>(&'a StoreReader<'b>);
impl CommitView for View<'_, '_> {
    type Error = CellError;
    fn pending(&self, _: &Consumed) -> Result<bool, CellError> {
        panic!("no consumed input in admission model")
    }
    fn version(&self, key: &FactKey) -> Result<FactVersion, CellError> {
        self.0
            .version("main", key.object_type.as_str(), &key.key)
            .map(FactVersion)
    }
    fn concrete(&self, key: &FactKey) -> Result<Option<ObjectTypeName>, CellError> {
        self.0
            .object("main", key.object_type.as_str(), &key.key)
            .map(|row| row.map(|r| ObjectTypeName(r.object_type)))
    }
    fn link_version(&self, _: &LinkKey) -> Result<FactVersion, CellError> {
        panic!("no links in admission model")
    }
    fn links_of(&self, _: &FactKey) -> Result<Vec<LinkKey>, CellError> {
        Ok(vec![])
    }
}

#[test]
fn commit_admission_quint_traces() {
    let covered = replay_admission(traces("commit-admission"));
    for verdict in [
        "commit", "replay", "conflict", "stale", "rollback", "lost_ack",
    ] {
        assert!(
            covered.contains(verdict),
            "trace seeds did not exercise {verdict}"
        );
    }
    eprintln!("commit admission coverage: {covered:?}");
}

fn replay_admission(trace_files: Vec<(PathBuf, Vec<Value>)>) -> BTreeSet<String> {
    let mut covered = BTreeSet::new();
    for (path, states) in trace_files {
        let dir = tempfile::tempdir().expect("temporary cell");
        let db = dir.path().join("cell.sqlite");
        let definitions = model();
        let mut store = CellStore::open(&db, model(), StoreOptions::default()).expect("cell");
        store.bind("scope", "tenant/proof").expect("bind");
        let catalog = TypeCatalog::new(definitions.object_types());
        let commit_model = CommitModel::new(&catalog);
        for (index, state) in states.iter().enumerate().skip(1) {
            let r = &state["request"];
            let owner = number(&r["owner"]);
            let expected = u64::try_from(number(&r["expected"])).expect("version");
            let key = format!("key-{}", number(&r["key"]));
            let values = BTreeMap::from([("v".into(), runtime(r["input"].clone()))]);
            let event = runtime(json!({"owner":owner,"expected":expected,"input":r["input"]}));
            let commit: CellCommit<RuntimeValue, String, String> = CellCommit {
                writes: vec![FactWrite {
                    key: FactKey::new("proof.Marker", owner.to_string()),
                    expected: FactVersion(expected),
                    mutation: FactMutation::Put {
                        values: values.clone(),
                    },
                }],
                ..CellCommit::default()
            };
            let batch = CommitBatch {
                world: "main".into(),
                scope: "tenant/proof".into(),
                idempotency_key: Some(key.clone()),
                writes: vec![FactWriteRow::Put {
                    object_type: "proof.Marker".into(),
                    key: owner.to_string(),
                    values,
                }],
                events: vec![event],
                effects: vec![EffectRow::Enqueue {
                    command: OutboxCommand {
                        command_id: key.clone(),
                        generation: 0,
                        idempotency_key: key.clone(),
                        deadline: None,
                        command: runtime(json!("proof effect")),
                    },
                }],
                ..CommitBatch::default()
            };
            let seam = number(&r["seam"]);
            let point = match seam {
                1 => CommitPoint::FactsApplied,
                2 => CommitPoint::LinksApplied,
                3 => CommitPoint::EventsAppended,
                4 => CommitPoint::EffectsEnqueued,
                5 => CommitPoint::ReceiptWritten,
                _ => CommitPoint::Committed,
            };
            let before = store.read().dump().expect("before");
            let prior = store
                .read()
                .receipt_by_idempotency_key("main", &key)
                .expect("prior receipt");
            let result = store.commit_guarded(
                &batch,
                |reader| check_commit(&commit, &commit_model, &View(reader)).map(|_| ()),
                &mut |at| {
                    if seam != 0 && at == point {
                        Err(CellError::Engine("proof interruption".into()))
                    } else {
                        Ok(())
                    }
                },
            );
            let actual = match result {
                Ok(((), CommitOutcome::Committed(_))) => "commit",
                Ok(((), CommitOutcome::Replayed(receipt))) => {
                    assert_eq!(
                        Some(receipt),
                        prior,
                        "replay must return the exact first receipt"
                    );
                    "replay"
                }
                Err(GuardedError::Guard(CommitError::Conflict { .. })) => "stale",
                Err(GuardedError::Store(CellError::IdempotencyConflict(_))) => "conflict",
                Err(GuardedError::Store(CellError::Engine(ref message)))
                    if message == "proof interruption" =>
                {
                    if seam == 6 {
                        "lost_ack"
                    } else {
                        "rollback"
                    }
                }
                other => panic!("{}:{index}: unexpected {other:?}", path.display()),
            };
            assert_eq!(
                actual,
                text(&state["outcome"]),
                "{}:{index}",
                path.display()
            );
            covered.insert(actual.to_owned());
            let durable = &state["durable"];
            for owner in 0..2 {
                let object = store
                    .read()
                    .object("main", "proof.Marker", &owner.to_string())
                    .expect("object");
                assert_eq!(
                    store
                        .read()
                        .version("main", "proof.Marker", &owner.to_string())
                        .expect("version"),
                    u64::try_from(number(&durable["versions"][owner])).expect("version")
                );
                if let Some(object) = object {
                    assert_eq!(
                        serde_json::to_value(&object.values["v"]).expect("value"),
                        durable["values"][owner]
                    );
                } else {
                    assert_eq!(number(&durable["values"][owner]), 0);
                }
            }
            let count = usize::try_from(number(&durable["commits"])).expect("count");
            let commands = store.read().pending_commands().expect("queued commands");
            assert_eq!(
                commands.len(),
                usize::try_from(number(&durable["effects"])).expect("effect count")
            );
            assert_eq!(
                store.read().ledger(0).expect("events").len(),
                usize::try_from(number(&durable["events"])).expect("event count")
            );
            for receipt_key in 0..4 {
                let identity = format!("key-{receipt_key}");
                let receipt = store
                    .read()
                    .receipt_by_idempotency_key("main", &identity)
                    .expect("receipt lookup");
                let expected_input = number(&durable["inputs"][receipt_key]);
                assert_eq!(receipt.is_some(), expected_input != 0);
                let queued = commands
                    .iter()
                    .find(|row| row.command.command_id == identity);
                assert_eq!(queued.is_some(), expected_input != 0);
                if let Some(receipt) = receipt {
                    assert_eq!(receipt.body.event_count, 1);
                    assert_eq!(receipt.body.enqueued, vec![identity.clone()]);
                    assert_eq!(receipt.body.written.len(), 1);
                    assert_eq!(
                        receipt.body.written[0].version,
                        u64::try_from(
                            number(&durable["expected"][receipt_key])
                                .checked_add(1)
                                .expect("bounded receipt version")
                        )
                        .expect("receipt version")
                    );
                    let event = store
                        .read()
                        .ledger(receipt.body.first_event_seq)
                        .expect("receipt event")[0]
                        .event
                        .clone();
                    assert_eq!(
                        serde_json::to_value(event).expect("event"),
                        json!({
                        "owner":durable["owners"][receipt_key], "expected":durable["expected"][receipt_key],
                        "input":expected_input })
                    );
                    let queued = queued.expect("exact durable effect");
                    assert_eq!(queued.command.idempotency_key, identity);
                    assert_eq!(queued.command.generation, 0);
                    assert_eq!(
                        serde_json::to_value(&queued.command.command).expect("effect"),
                        json!("proof effect")
                    );
                }
            }
            assert_eq!(
                store.read().pending_commands().expect("outbox").len(),
                count
            );
            assert_eq!(store.read().ledger(0).expect("ledger").len(), count);
            assert_eq!(
                store.read().dump().expect("dump")["_norn_receipt"].len(),
                count
            );
            if matches!(actual, "replay" | "conflict" | "stale" | "rollback") {
                assert_eq!(before, store.read().dump().expect("after refused turn"));
            }
            store
                .read()
                .verify_ledger()
                .expect("verified chain and receipts");
            drop(store);
            store =
                CellStore::open(&db, model(), StoreOptions::default()).expect("reopen every turn");
        }
    }
    covered
}

#[test]
fn commit_admission_trace_mutants_fail() {
    let (path, states) = traces("commit-admission")
        .into_iter()
        .find(|(_, states)| {
            states
                .iter()
                .any(|s| s["outcome"] == "commit" || s["outcome"] == "lost_ack")
        })
        .expect("accepted transition in corpus");
    let index = states
        .iter()
        .position(|s| s["outcome"] == "commit" || s["outcome"] == "lost_ack")
        .expect("accepted state");
    for field in ["outcome", "versions", "effects", "inputs"] {
        let mut altered = states[..=index].to_vec();
        let state = &mut altered[index];
        match field {
            "outcome" => state["outcome"] = json!("stale"),
            "versions" => {
                state["durable"]["versions"][0] =
                    json!(number(&state["durable"]["versions"][0]) + 1);
            }
            "effects" => {
                state["durable"]["effects"] = json!(number(&state["durable"]["effects"]) + 1);
            }
            "inputs" => {
                let key = usize::try_from(number(&state["request"]["key"])).expect("key");
                state["durable"]["inputs"][key] = json!(0);
            }
            _ => unreachable!(),
        }
        assert!(
            std::panic::catch_unwind(|| replay_admission(vec![(path.clone(), altered)])).is_err(),
            "adapter accepted divergent model {field}"
        );
    }
}

fn pack() -> Value {
    let mut templates = vec![];
    let mut fund = vec![];
    for p in 0..4 {
        let unit = format!("u{}", p / 2);
        let layer = format!("l{}", p % 2);
        for (id, account, coefficient) in [
            ("issue", "issuance", -2),
            ("a", "lot0", 1),
            ("b", "lot1", 1),
        ] {
            fund.push(leg(
                &format!("{id}{p}"),
                account,
                &unit,
                &layer,
                coefficient,
                "q",
            ));
        }
        for slot in 0..2 {
            templates.push(json!({"templateId":format!("move{p}-{slot}"),
                "parameters":[parameter("out"),parameter("back")],
                "legs":[leg("out", &format!("lot{slot}"), &unit, &layer, -1, "out"),
                    leg("back", &format!("lot{slot}"), &unit, &layer, 1, "back"),
                    {"legId":"dest","accountId":"dest","unitId":unit,"layer":layer,
                     "amount":{"resultScale":0,"constantUnscaled":"0","constantScale":0,
                       "terms":[{"parameterId":"out","coefficientUnscaled":"1","coefficientScale":0},
                                {"parameterId":"back","coefficientUnscaled":"-1","coefficientScale":0}]}}]}));
        }
    }
    templates.push(json!({"templateId":"fund","parameters":[parameter("q")],"legs":fund}));
    json!({"irVersion":norn_ir::quantity_ledger::LEDGER_PACK_IR_VERSION,"packId":"proof",
        "ontologyArtifact":{"artifactId":"units","artifactVersion":"1","artifactSha256":"a".repeat(64)},
        "units":[{"unitId":"u0","unitTermId":"unit0","quantityKindTermId":"kind0","precision":0},
                 {"unitId":"u1","unitTermId":"unit1","quantityKindTermId":"kind1","precision":0}],
        "layers":[{"layerId":"l0"},{"layerId":"l1"}],
        "accounts":[{"accountId":"issuance","allowedUnitIds":["u0","u1"]},
                    {"accountId":"lot0","allowedUnitIds":["u0","u1"]},
                    {"accountId":"lot1","allowedUnitIds":["u0","u1"],"funding":"net"},
                    {"accountId":"dest","allowedUnitIds":["u0","u1"]}],"templates":templates})
}
fn parameter(id: &str) -> Value {
    json!({"parameterId":id,"scale":0,"minUnscaled":"0","maxUnscaled":"10"})
}
fn leg(
    id: &str,
    account: &str,
    unit: &str,
    layer: &str,
    coefficient: i64,
    parameter: &str,
) -> Value {
    json!({"legId":id,"accountId":account,"unitId":unit,"layer":layer,
        "amount":{"resultScale":0,"constantUnscaled":"0","constantScale":0,
            "terms":[{"parameterId":parameter,"coefficientUnscaled":coefficient.to_string(),"coefficientScale":0}]}})
}
fn request(operation: Value, fences: Vec<Value>) -> QuantityRequest {
    let packet = Value::Object(serde_json::Map::from_iter([
        ("version".into(), json!("norn.quantity.commit/2")),
        ("ledgerId".into(), json!("proof")),
        ("balanceVersions".into(), Value::Array(fences)),
        ("operation".into(), operation),
    ]));
    serde_json::from_value(packet)
        .expect("quantity v2 requires #3356; never reinterpret a v2 trace as v1")
}

fn fence(i: usize, version: i64) -> Value {
    json!({"account":(["issuance","lot0","lot1","dest"][i % 4]),
        "unit":format!("u{}", i / 8),"layer":format!("l{}", (i / 4) % 2),"version":version})
}
fn initialized(db: &Path) -> CellStore {
    assert_eq!(
        norn_ir::quantity_ledger::QUANTITY_CELL_VERSION,
        "norn.quantity.commit/2",
        "v2 conformance needs #3356 and an isolated build target"
    );
    let mut store = CellStore::open(db, model(), StoreOptions::default()).expect("cell");
    store.bind("scope", "tenant/proof").expect("scope");
    commit_quantity(
        &mut store,
        request(
            json!({"kind":"define","account_limit":4,"pack":pack(),
        "unrestricted_accounts":["issuance"]}),
            vec![],
        ),
        "define",
        0,
        None,
    )
    .expect("define v2");
    let fences = (0..16)
        .filter(|i| i % 4 != 3)
        .map(|i| fence(i, 0))
        .collect();
    commit_quantity(
        &mut store,
        request(
            json!({"kind":"post","posting_id":"fund","template_id":"fund",
        "parameters":[{"parameterId":"q","scale":0,"unscaled":"2"}]}),
            fences,
        ),
        "fund",
        0,
        None,
    )
    .expect("fund");
    store
}
fn commit_quantity(
    store: &mut CellStore,
    quantity: QuantityRequest,
    key: &str,
    now: u64,
    consumes: Option<Consumption>,
) -> Result<CommitOutcome, CellError> {
    store.commit(&CommitBatch {
        world: "main".into(),
        scope: "tenant/proof".into(),
        logical_time: now,
        idempotency_key: Some(key.into()),
        quantity: Some(quantity),
        consumes,
        ..CommitBatch::default()
    })
}
fn quantity_error(result: &Result<CommitOutcome, CellError>) -> &str {
    use norn_kernel::quantity::QuantityError as Q;
    match result {
        Ok(CommitOutcome::Committed(_)) => "commit",
        Err(CellError::Quantity(Q::ClockRegression)) => "clock",
        Err(CellError::Quantity(Q::Terminal)) => "terminal",
        Err(CellError::Quantity(Q::Duplicate)) => "duplicate",
        Err(CellError::Quantity(Q::InvalidContract)) => "invalid",
        Err(CellError::Quantity(Q::Expired)) => "expired",
        Err(CellError::Quantity(Q::NotExpired)) => "not_expired",
        Err(CellError::Quantity(Q::StaleVersion { .. })) => "stale",
        Err(CellError::Quantity(Q::InsufficientAvailable { .. })) => "funding",
        other => panic!("unexpected quantity outcome {other:?}"),
    }
}

#[test]
fn quantity_v2_quint_traces() {
    let mut coverage = BTreeSet::new();
    let mut mismatches = BTreeMap::<String, (usize, String)>::new();
    for (path, states) in traces("quantity-ledger") {
        let dir = tempfile::tempdir().expect("directory");
        let db = dir.path().join("cell.sqlite");
        let mut store = initialized(&db);
        for (index, state) in states.iter().enumerate().skip(1) {
            let r = &state["request"];
            let kind = text(&r["kind"]);
            if kind == "snapshot" {
                assert_quantity_state(&store, &state["state"], &db);
                continue;
            }
            let slot = number(&r["slot"]);
            let partition = number(&r["partition"]);
            let reservation = format!("r{slot}");
            let release = matches!(
                kind,
                "post_slice" | "void_slice" | "lazy_expire" | "scheduled_expire"
            );
            let operation = match kind {
                "post" | "reserve" => {
                    json!({"kind":kind,"template_id":format!("move{partition}-{slot}"),
                    "parameters":[{"parameterId":"out","scale":0,"unscaled":number(&r["out"]).to_string()},
                        {"parameterId":"back","scale":0,"unscaled":number(&r["back"]).to_string()}]})
                }
                "post_slice" | "void_slice" => {
                    let legs = [
                        ("out", -number(&r["out"])),
                        ("back", number(&r["back"])),
                        ("dest", number(&r["dest"])),
                    ]
                    .into_iter()
                    .filter(|(_, n)| *n != 0)
                    .map(|(id, n)| json!({"legId":id,"amountUnscaled":n.to_string()}))
                    .collect::<Vec<_>>();
                    json!({"kind":if kind == "post_slice" {"post_reservation"} else {"void"},
                        "reservation_id":reservation,"resolution":{"kind":"subset","legs":legs}})
                }
                "lazy_expire" | "scheduled_expire" => {
                    json!({"kind":"expire","reservation_id":reservation})
                }
                "ordinary" => json!({}),
                other => panic!("unknown action {other}"),
            };
            let mut operation = operation;
            if matches!(kind, "post" | "post_slice") {
                operation["posting_id"] = json!(format!("post{index}"));
            }
            if kind == "reserve" {
                operation["reservation_id"] = json!(reservation);
                operation["expires_at"] = json!(3);
            }
            let previous = &state["before"];
            let old = &previous["reservations"][usize::try_from(slot).expect("slot")];
            let gross = slot == 0;
            let old_hold = if release {
                number(&old["out"]) - if gross { 0 } else { number(&old["back"]) }
            } else {
                0
            };
            let selected_hold = number(&r["out"]) - if gross { 0 } else { number(&r["back"]) };
            let new_hold = old_hold - selected_hold;
            let posted = matches!(kind, "post" | "post_slice");
            let src_delta = if posted {
                number(&r["back"]) - number(&r["out"])
            } else {
                0
            };
            let hold_delta = if release {
                new_hold - old_hold
            } else if kind == "reserve" {
                selected_hold
            } else {
                0
            };
            let src = usize::try_from(partition * 4 + slot + 1).expect("source");
            let dst = usize::try_from(partition * 4 + 3).expect("destination");
            let mut fences = vec![];
            if src_delta != 0
                || hold_delta != 0
                || (matches!(kind, "post" | "reserve" | "post_slice") && selected_hold > 0)
            {
                fences.push(fence(src, number(&r["sourceVersion"])));
            }
            if posted && number(&r["dest"]) != 0 {
                fences.push(fence(dst, number(&r["destVersion"])));
            }
            let before = store.read().dump().expect("before");
            let now = u64::try_from(number(&r["now"])).expect("time");
            let mut consumes = None;
            if kind == "scheduled_expire" && text(&old["status"]) == "open" && now >= 3 {
                let timers = store.read().pending_timers().expect("timers");
                let timer = timers
                    .iter()
                    .find(|timer| {
                        serde_json::to_value(&timer.timer.timer).expect("timer")["reservation"]
                            == reservation
                    })
                    .expect("durable deadline");
                consumes = Some(Consumption::Timer {
                    timer_id: timer.timer.timer_id.clone(),
                    incarnation: timer.commit_seq,
                });
            }
            let result = if kind == "ordinary" {
                store.commit(&CommitBatch {
                    world: "main".into(),
                    scope: "tenant/proof".into(),
                    logical_time: now,
                    idempotency_key: Some(format!("turn{index}")),
                    events: vec![runtime(json!({"type":"proof.clock"}))],
                    ..CommitBatch::default()
                })
            } else {
                commit_quantity(
                    &mut store,
                    request(operation, fences),
                    &format!("turn{index}"),
                    now,
                    consumes,
                )
            };
            let actual = quantity_error(&result);
            let expected = text(&state["outcome"]);
            if actual != expected {
                let entry = mismatches
                    .entry(format!("{kind}: expected {expected}, actual {actual}"))
                    .or_insert_with(|| (0, format!("{}:{index}: {r} {result:?}", path.display())));
                entry.0 += 1;
            }
            coverage.insert(format!("{kind}:{actual}"));
            if actual != "commit" {
                assert_eq!(before, store.read().dump().expect("rejected unchanged"));
            }
            assert_quantity_state(&store, &state["state"], &db);
            let dump = store.read().dump().expect("dump");
            drop(store);
            store =
                CellStore::open(&db, model(), StoreOptions::default()).expect("verified reopen");
            assert_eq!(dump, store.read().dump().expect("reopened dump"));
        }
    }
    for event in [
        "reserve:commit",
        "post_slice:commit",
        "void_slice:commit",
        "lazy_expire:commit",
        "scheduled_expire:commit",
        "ordinary:commit",
        "post:stale",
        "post:funding",
        "post_slice:expired",
        "ordinary:clock",
    ] {
        assert!(
            coverage.contains(event),
            "trace seeds did not exercise {event}: {coverage:?}"
        );
    }
    eprintln!("quantity v2 coverage: {coverage:?}");
    assert!(
        mismatches.is_empty(),
        "typed conformance mismatches (all state comparisons still enforced): {mismatches:#?}"
    );
}
fn assert_quantity_state(store: &CellStore, expected: &Value, db: &Path) {
    let engine = NativeEngine::open(db, StoreOptions::default()).expect("clock reader");
    let (floor, sequence): (i64, i64) = engine
        .query_row(
            "SELECT logical_time,commit_seq FROM _norn_clock WHERE id=1",
            &[],
            |row| Ok((row.get(0)?, row.get(1)?)),
        )
        .expect("persisted cell clock");
    assert_eq!(floor, number(&expected["floor"]));
    assert_eq!(
        sequence,
        number(&expected["commits"])
            .checked_add(2)
            .expect("bounded commit sequence")
    );
    let timers = store.read().pending_timers().expect("expiry timers");
    let open = expected["reservations"]
        .as_array()
        .expect("reservations")
        .iter()
        .filter(|r| r["status"] == "open")
        .count();
    assert_eq!(
        timers.len(),
        open,
        "one durable deadline per open remainder"
    );
    for i in 0..16 {
        let key = norn_kernel::quantity::QuantityKey {
            account: ["issuance", "lot0", "lot1", "dest"][i % 4].into(),
            unit: format!("u{}", i / 8),
            layer: format!("l{}", (i / 4) % 2),
        };
        let actual = serde_json::to_value(
            store
                .read()
                .quantity_balance("main", "proof", &key)
                .expect("balance"),
        )
        .expect("serialize");
        assert_eq!(
            text(&actual["posted"]),
            number(&expected["posted"][i]).to_string()
        );
        assert_eq!(
            text(&actual["held"]),
            number(&expected["held"][i]).to_string()
        );
        assert_eq!(actual["version"], expected["versions"][i]);
    }
    for i in 0..2 {
        let actual = store
            .read()
            .quantity_reservation("main", "proof", &format!("r{i}"))
            .expect("reservation");
        let r = &expected["reservations"][i];
        if text(&r["status"]) == "missing" {
            assert!(actual.is_none());
            continue;
        }
        let actual = serde_json::to_value(actual.expect("present")).expect("serialize");
        assert_eq!(actual["status"], r["status"]);
        assert_eq!(actual["expiresAt"], 3);
        for (leg, field, sign) in [("out", "out", -1), ("back", "back", 1), ("dest", "dest", 1)] {
            let remaining = actual["remaining"]
                .as_array()
                .expect("remaining")
                .iter()
                .find(|l| l["legId"] == leg)
                .map_or(0, |l| {
                    text(&l["amountUnscaled"]).parse::<i64>().expect("amount")
                });
            assert_eq!(
                remaining,
                number(&r[field])
                    .checked_mul(sign)
                    .expect("bounded signed slice")
            );
        }
    }
}

#[test]
fn projection_trust_quint_traces() {
    let mut coverage = BTreeSet::new();
    for (path, states) in traces("projection-trust") {
        let dir = tempfile::tempdir().expect("directory");
        let db = dir.path().join("cell.sqlite");
        let mut store = Some(initialized(&db));
        let mut projection = 0_i64;
        let mut intact_ledger = Vec::new();
        for (index, state) in states.iter().enumerate().skip(1) {
            match text(&state["command"]) {
                "append" => {
                    let amount = number(&state["amount"]);
                    let cell = store.as_mut().expect("opened");
                    let key = norn_kernel::quantity::QuantityKey {
                        account: "issuance".into(),
                        unit: "u0".into(),
                        layer: "l0".into(),
                    };
                    let original = serde_json::to_value(
                        cell.read()
                            .quantity_balance("main", "proof", &key)
                            .expect("balance"),
                    )
                    .expect("serialize");
                    // Use the production balanced fund template: all partitions get n.
                    let fences = (0..16)
                        .filter(|i| i % 4 != 3)
                        .map(|i| fence(i, number(&original["version"])))
                        .collect();
                    commit_quantity(cell,request(json!({"kind":"post","posting_id":format!("p{index}"),"template_id":"fund",
                        "parameters":[{"parameterId":"q","scale":0,"unscaled":amount.to_string()}]}),fences),&format!("p{index}"),0,None).expect("immutable transition");
                    projection += amount;
                    cell.read().verify_ledger().expect("intact immutable chain");
                }
                "tamper" => {
                    drop(store.take());
                    projection += 1;
                    let engine = NativeEngine::open(&db, StoreOptions::default()).expect("engine");
                    intact_ledger = engine
                        .query("SELECT * FROM _norn_ledger ORDER BY seq", &[])
                        .expect("immutable chain before forgery");
                    // Forge both caches consistently: matching history is insufficient.
                    for table in ["_norn_quantity_balance", "_norn_quantity_history"] {
                        engine.execute(&format!("UPDATE \"{table}\" SET \"posted\"=?1 WHERE \"account\"='lot0' AND \"unit\"='u0' AND \"layer\"='l0'"),
                            &[norn_cell::engine::SqlValue::Text((2+projection).to_string())]).expect("forge projection");
                    }
                }
                "corrupt_chain" => {
                    drop(store.take());
                    let engine = NativeEngine::open(&db, StoreOptions::default()).expect("engine");
                    engine
                        .execute(
                            "UPDATE \"_norn_ledger\" SET \"hash\"=?1 WHERE \"seq\"=1",
                            &["f".repeat(64).into()],
                        )
                        .expect("corrupt immutable chain");
                }
                "reopen" => {
                    drop(store.take());
                    let chain_intact = state["chainIntact"].as_bool().expect("chain flag");
                    let folded: i64 = state["transitions"]
                        .as_array()
                        .expect("transitions")
                        .iter()
                        .map(number)
                        .sum();
                    let context = if !chain_intact {
                        "chain_corrupt"
                    } else if projection != folded {
                        "coherent_cache_forgery"
                    } else {
                        "normal"
                    };
                    if context == "coherent_cache_forgery" {
                        let engine = NativeEngine::open(&db, StoreOptions::default())
                            .expect("forgery reader");
                        assert_eq!(
                            intact_ledger,
                            engine
                                .query("SELECT * FROM _norn_ledger ORDER BY seq", &[])
                                .expect("immutable chain after forgery")
                        );
                        assert!(
                            !intact_ledger.is_empty(),
                            "forgery must retain committed immutable evidence"
                        );
                        let balance = engine.query("SELECT posted, held, version FROM _norn_quantity_balance WHERE account='lot0' AND unit='u0' AND layer='l0'", &[]).expect("forged balance");
                        let history = engine.query("SELECT posted, held, version FROM _norn_quantity_history WHERE account='lot0' AND unit='u0' AND layer='l0' ORDER BY version DESC LIMIT 1", &[]).expect("forged history");
                        assert_eq!(balance, history, "both forged mutable caches agree");
                    }
                    let result = CellStore::open(&db, model(), StoreOptions::default());
                    assert_eq!(
                        result.is_ok(),
                        text(&state["outcome"]) == "open",
                        "{}:{index}",
                        path.display()
                    );
                    if context == "coherent_cache_forgery" {
                        assert!(
                            matches!(
                                &result,
                                Err(CellError::Quantity(
                                    norn_kernel::quantity::QuantityError::Corrupt
                                ))
                            ),
                            "intact-chain cache forgery must fail quantity replay"
                        );
                    }
                    if context != "coherent_cache_forgery" || folded > 0 {
                        coverage.insert(context);
                    }
                    if context == "coherent_cache_forgery" && folded > 0 {
                        eprintln!(
                            "intact-chain coherent-cache reopen refused: {}:{index}",
                            path.display()
                        );
                    }
                    match result {
                        Ok(cell) => store = Some(cell),
                        Err(
                            CellError::Quantity(norn_kernel::quantity::QuantityError::Corrupt)
                            | CellError::LedgerCorrupt { .. },
                        ) => {}
                        Err(other) => panic!("unexpected reopen refusal: {other:?}"),
                    }
                }
                other => panic!("unknown projection action {other}"),
            }
            assert_eq!(projection, number(&state["projected"]));
            let engine =
                NativeEngine::open(&db, StoreOptions::default()).expect("projection reader");
            let stored: String = engine.query_row(
                "SELECT posted FROM _norn_quantity_balance WHERE account='lot0' AND unit='u0' AND layer='l0'",
                &[], |row| row.get(0)).expect("actual projection");
            assert_eq!(
                stored.parse::<i64>().expect("exact projection") - 2,
                number(&state["projected"]),
                "projection differs from Quint fold"
            );
            let count: i64 = engine
                .query_row(
                    "SELECT COUNT(*) FROM _norn_quantity_posting WHERE id != 'fund'",
                    &[],
                    |row| row.get(0),
                )
                .expect("immutable posting count");
            assert_eq!(
                usize::try_from(count).expect("count"),
                state["transitions"].as_array().expect("transitions").len()
            );
        }
    }
    for context in ["normal", "coherent_cache_forgery", "chain_corrupt"] {
        assert!(
            coverage.contains(context),
            "projection trace seeds did not exercise {context}: {coverage:?}"
        );
    }
    eprintln!("projection reopen coverage: {coverage:?}");
}

#[test]
fn quantity_closed_slice_refusal_matches_pure_kernel() {
    use norn_kernel::quantity::{QuantityError, QuantityState, prepare_quantity};
    let dir = tempfile::tempdir().expect("directory");
    let db = dir.path().join("cell.sqlite");
    let mut store = initialized(&db);
    let reserve = request(
        json!({"kind":"reserve","reservation_id":"r0", "template_id":"move0-0",
        "parameters":[{"parameterId":"out","scale":0,"unscaled":"2"},
                      {"parameterId":"back","scale":0,"unscaled":"0"}], "expires_at":3}),
        vec![fence(1, 1)],
    );
    commit_quantity(&mut store, reserve, "reserve", 0, None).expect("reserve");
    let void = request(
        json!({"kind":"void","reservation_id":"r0","resolution":{"kind":"all"}}),
        vec![fence(1, 2)],
    );
    commit_quantity(&mut store, void, "void", 0, None).expect("terminal void");
    let closed = store
        .read()
        .quantity_reservation("main", "proof", "r0")
        .expect("read")
        .expect("closed record");
    assert_eq!(closed.status, "void");
    let subset = request(
        json!({"kind":"void","reservation_id":"r0", "resolution":{"kind":"subset",
        "legs":[{"legId":"out","amountUnscaled":"-1"},{"legId":"dest","amountUnscaled":"1"}]}}),
        vec![],
    );
    let state = QuantityState {
        version: store
            .read()
            .quantity_version("main", "proof")
            .expect("version"),
        pack: Some(serde_json::from_value(pack()).expect("pack")),
        reservation: Some(closed),
        ..QuantityState::default()
    };
    assert_eq!(
        prepare_quantity(&subset, &state, 0).expect_err("kernel refuses"),
        QuantityError::Terminal
    );
    let before = store.read().dump().expect("before refused request");
    let actual =
        commit_quantity(&mut store, subset, "closed-subset", 0, None).expect_err("cell refuses");
    assert_eq!(before, store.read().dump().expect("refusal is atomic"));
    assert!(
        matches!(actual, CellError::Quantity(QuantityError::Terminal)),
        "pure kernel refuses Terminal; cell refused {actual:?}"
    );
}
